// Abgabe-Seite eines Kindes: Office-Dateien gleich eingebettet zeigen (24. 11. 2026)
const ivCache = new Map();
async function inlineVorschau(el) {
  const f = { url: el.dataset.ivUrl, n: el.dataset.ivN || "" };
  el.dataset.ivFertig = "1";
  if (!f.url || !OFFICE.test(f.n)) { el.remove(); return; }
  el.style.margin = "2px 0 10px";
  el.innerHTML = '<div class="mv-info" style="padding:16px;text-align:center;color:var(--muted)">Vorschau wird geladen …</div>';
  try {
    let p = ivCache.get(f.url);
    if (!p) {
      p = fetch(f.url, { credentials: "same-origin" }).then((r) => { if (!r.ok) throw new Error("HTTP " + r.status); return r.arrayBuffer(); });
      ivCache.set(f.url, p);
      if (ivCache.size > 12) ivCache.delete(ivCache.keys().next().value);
    }
    const [mv, daten] = await Promise.all([officeModul(), p]);
    if (el.isConnected) await mv.zeigen(el, daten.slice(0), f.n);
  } catch (x) {
    ivCache.delete(f.url);
    console.warn("Office-Vorschau:", x);
    const i = el.querySelector(".mv-info");
    if (i) i.textContent = "Für diese Datei klappt die Vorschau hier nicht. Tippe auf „Ansehen“ oder lade sie herunter.";
  }
}
let ivPlan = false;
new MutationObserver(() => {
  if (ivPlan) return;
  ivPlan = true;
  requestAnimationFrame(() => { ivPlan = false; document.querySelectorAll(".inline-vorschau[data-iv-url]:not([data-iv-fertig])").forEach(inlineVorschau); });
}).observe(document.documentElement, { childList: true, subtree: true });

